INSERT INTO caddie_procs (idproc, type, name, requete, comment, autorisations, autorisations_all, parameters) VALUES (21,'ACTION','Changement de type de document des notices d\'un panier',0x757064617465206E6F74696365732073657420747970646F633D21216E65775F747970646F632121207768657265206E6F746963655F696420696E2028434144444945284E4F54492929,'','1',0,'<?xml version=\"1.0\" encoding=\"iso-8859-1\"?><FIELDS><FIELD NAME=\"new_typdoc\" MANDATORY=\"yes\">\n<ALIAS><![CDATA[Nouveau type de document]]></ALIAS>\n<TYPE>list</TYPE>\n<OPTIONS FOR=\"list\">\n<ITEMS>\n<ITEM VALUE=\"b\">texte manuscrit</ITEM>\n<ITEM VALUE=\"c\">partition musicale imprimée</ITEM>\n<ITEM VALUE=\"d\">partition musicale manuscrite</ITEM>\n<ITEM VALUE=\"e\">document cartographique imprimé</ITEM>\n<ITEM VALUE=\"f\">document cartographique manuscrit</ITEM>\n<ITEM VALUE=\"g\">document projeté ou vidéo</ITEM>\n<ITEM VALUE=\"i\">enregistrement sonore non musical</ITEM>\n<ITEM VALUE=\"j\">enregistrement sonore musical</ITEM>\n<ITEM VALUE=\"k\">document graphique à deux dimensions</ITEM>\n<ITEM VALUE=\"l\">document électronique</ITEM>\n<ITEM VALUE=\"m\">document multimédia</ITEM>\n<ITEM VALUE=\"r\">objet à 3 dimensions, artefacts, ...</ITEM>\n</ITEMS>\n<MULTIPLE>no</MULTIPLE>\n<UNSELECT_ITEM VALUE=\"a\">texte imprimé</UNSELECT_ITEM>\n</OPTIONS>\n</FIELD>\n</FIELDS>');
INSERT INTO caddie_procs (idproc, type, name, requete, comment, autorisations, autorisations_all, parameters) VALUES (22,'ACTION','Changement de message des exemplaires d\'un panier',0x757064617465206578656D706C616972657320736574206578706C5F6E6F74653D2721216E65775F6E6F7465212127207768657265206578706C5F696420696E2028434144444945284558504C2929,'','1',0,'<?xml version=\"1.0\" encoding=\"iso-8859-1\"?><FIELDS><FIELD NAME=\"new_note\" MANDATORY=\"no\">\n<ALIAS><![CDATA[Nouveau message]]></ALIAS>\n<TYPE>text</TYPE>\n<OPTIONS FOR=\"text\">\n<SIZE>25</SIZE>\n<MAXSIZE>25</MAXSIZE>\n</OPTIONS>\n</FIELD>\n</FIELDS>');
INSERT INTO caddie_procs (idproc, type, name, requete, comment, autorisations, autorisations_all, parameters) VALUES (23,'ACTION','Changement d\'une partie de la cote des exemplaires d\'un panier',0x757064617465206578656D706C616972657320736574206578706C5F636F74653D7265706C616365286578706C5F636F74652C202721216D6F7469665F312121272C202721216D6F7469665F3221212729207768657265206578706C5F696420696E2028434144444945284558504C2929,'','1',0,'<?xml version=\"1.0\" encoding=\"iso-8859-1\"?><FIELDS><FIELD NAME=\"motif_1\" MANDATORY=\"yes\">\n<ALIAS><![CDATA[Remplacer]]></ALIAS>\n<TYPE>text</TYPE>\n<OPTIONS FOR=\"text\">\n<SIZE>50</SIZE>\n<MAXSIZE>50</MAXSIZE>\n</OPTIONS>\n</FIELD>\n<FIELD NAME=\"motif_2\" MANDATORY=\"no\">\n<ALIAS><![CDATA[Par]]></ALIAS>\n<TYPE>text</TYPE>\n<OPTIONS FOR=\"text\">\n<SIZE>50</SIZE>\n<MAXSIZE>50</MAXSIZE>\n</OPTIONS>\n</FIELD>\n</FIELDS>');
