INSERT INTO cms_articles (id_article, article_title, article_resume, article_contenu, article_logo, article_publication_state, article_start_date, article_end_date, num_section, article_num_type, article_creation_date, article_order, article_update_timestamp) VALUES (70,'Les annales du disque-monde','Le disque-monde est plat, porté par quatre éléphants debout sur le dos\n d\'une tortue naviguant dans le cosmos. Tout le monde le sait et \nquoiqu\'en disent certaines sectes, c\'est la vérité. <br />Les héros de ce monde sont à son image : atypiques.<br /> Rincevent, \nmagicien malchanceux froussard et raté, ne connaît qu\'un seul sort mais \nil n\'ose pas le lancer car il pourrait tout détruire.<br /> Mémé \nCiredutemps, sorcière d\'un certain âge, ne peut que diriger tous ceux \nqui l\'entourent, elle ne fait d\'ailleurs que très rarement usage de sa \nmagie car tout le monde la connaît et lui obéit.<br /> La Mort, la faucheuse avec son grand suaire et sa faux bien aiguisée, grande humaniste incomprise.','<p>Les héros de ce monde sont à son image : atypiques.<br /> Rincevent, \nmagicien malchanceux froussard et raté, ne connaît qu\'un seul sort mais \nil n\'ose pas le lancer car il pourrait tout détruire.<br /> Mémé \nCiredutemps, sorcière d\'un certain âge, ne peut que diriger tous ceux \nqui l\'entourent, elle ne fait d\'ailleurs que très rarement usage de sa \nmagie car tout le monde la connaît et lui obéit.<br /> La Mort, la faucheuse avec son grand suaire et sa faux bien aiguisée, grande humaniste incomprise.  </p>Pratchett\n consacre chacun de ses romans à un de ces personnages même s\'il arrive \nqu\'ils se rencontrent de temps en temps, car tout est possible dans cet \nunivers totalement fou et plein d\'humour !',,2,'0000-00-00 00:00:00','0000-00-00 00:00:00',23,4,'2014-09-04 00:00:00',9,'2014-09-03 22:00:00');
INSERT INTO cms_articles (id_article, article_title, article_resume, article_contenu, article_logo, article_publication_state, article_start_date, article_end_date, num_section, article_num_type, article_creation_date, article_order, article_update_timestamp) VALUES (71,'Des bibliothèques pleines de fantômes','Avez-vous peur de mourir dans votre sommeil, enseveli sous l\'écroulement\n de votre bibliothèque ? Classez-vous les volumes par thème, langue, \nauteur, date de parution, format ou selon un autre critère de vous seul \nconnu ?','Autant de graves questions se posant à cette espèce en voie de disparition : les bibliomanes, qui, outre la passion de posséder les livres, ont celle de les lire. Les bibliothèques sont des êtres vivants à l\'image de notre complexité intérieure. Elles finissent par composer un labyrinthe dont pour notre plus grand, et dangereux, plaisir nous pouvons très bien ne plus sortir. Dans ce petit traité sur l\'art de vivre avec trop de livres apparaissent, parmi nombre d\'autres, Pessoa tentant de devenir bibliothécaire, Matisse postulant au poste de «contrôleur du droit des pauvres» ou encore le capitaine Achab et le mystère de sa jambe abandonnée à Moby Dick. En fait, ces milliers de pages qui occupent nos étagères sont peuplées de fantômes bien vivants qui, une fois rencontrés, ne nous quittent plus.',,2,'0000-00-00 00:00:00','0000-00-00 00:00:00',23,4,'2014-09-04 00:00:00',9,'2014-09-03 22:00:00');
INSERT INTO cms_articles (id_article, article_title, article_resume, article_contenu, article_logo, article_publication_state, article_start_date, article_end_date, num_section, article_num_type, article_creation_date, article_order, article_update_timestamp) VALUES (74,'Lire aussi','Titre du cadre :05_liste de notices<br />','','',3,'0000-00-00 00:00:00','0000-00-00 00:00:00',70,4,'2015-01-26 00:00:00',2,'2015-01-25 23:00:00');
