INSERT INTO notice_tplcode (num_notpl, notplcode_localisation, notplcode_typdoc, notplcode_niveau_biblio, notplcode_niveau_hierar, nottplcode_code) VALUES (1,0,'0','s','0','<table border=\"0\" cellpadding=\"1\" cellspacing=\"5\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"width:110px;text-align:center;\">\r\n\r\n<!-- affichage de la vignette avec un lien vers la notice / attention à personnaliser la vignette no_image.jpg en fonction du style -->\r\n<a href=\"#permalink();\">#if(#img_url();,<img src=\"#img_url();\" style=\"width:100px;\" />,<img src=\"./images/no_image.jpg\" style=\"width:100px;\" />);</a>\r\n\r\n                        </td>\r\n			<td style=\"text-align:left;\">\r\n\r\n<!-- affichage du titre + complément du titre avec un lien vers la notice -->\r\n<a href=\"#permalink();\"><font size=3>#title();#a_empty(#complement_title();, : );</font></a>\r\n\r\n<!-- URL associée -->\r\n#not_empty(#url();,<br />En ligne : <a href=\"#url();\" target=\"_blank\">#if(#extract_path(:\\/\\/([^\\/]*)\\/.,#url(););,#extract_path(:\\/\\/([^\\/]*)\\/.,#url(););[...],#extract_path(:\\/\\/([^\\/]*),#url();););</a>);\r\n\r\n<!-- affichage du résumé -->\r\n#a_empty(#resume();,<br /><br />);\r\n\r\n<!-- affichage des documents numériques -->\r\n#a_empty(#expl_num();,<br /><br />);\r\n\r\n                        </td>\r\n		</tr>\r\n	</tbody>\r\n</table>');
INSERT INTO notice_tplcode (num_notpl, notplcode_localisation, notplcode_typdoc, notplcode_niveau_biblio, notplcode_niveau_hierar, nottplcode_code) VALUES (1,0,'0','b','0','<table border=\"0\" cellpadding=\"1\" cellspacing=\"5\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"width:110px;text-align:center;\">\r\n\r\n<!-- affichage de la vignette avec un lien vers la notice / attention à personnaliser la vignette no_image.jpg en fonction du style -->\r\n<a href=\"#permalink();\">#if(#img_url();,<img src=\"#img_url();\" style=\"width:100px;\" />,<img src=\"./images/no_image.jpg\" style=\"width:100px;\" />);</a>\r\n\r\n                        </td>\r\n			<td style=\"text-align:left;\">\r\n\r\n<!-- affichage du titre + complément du titre avec un lien vers la notice -->\r\n#header_link(<font size=3>#if(#titre_bulletin();,#titre_bulletin();,#extract_path((.*) [(],#title();););#a_empty(#complement_title();, : );</font>,0);\r\n\r\n<!-- affichage des 3 premiers auteurs -->\r\n#str_replace(  , ,#a_empty(#authors_by_type_with_tpl(1,3,\\, ,\\, ,0,1,70\\,71\\,72,{rejete} {name});,<br />de ););\r\n\r\n<br />\r\n\r\n<!-- affichage des infos du périodique : titre / numéro / date / page -->\r\nBulletin de <i>#nom_revue();</i>#a_empty(#numero_bulletin();,\\, );#not_empty(#date_bulletin();, (#if(#extract_path((.*) [(],#date_bulletin(););,#extract_path((.*) [(],#date_bulletin(););,#extract_path([[](.*)[]],#title();););));#a_empty(#page();,\\, );\r\n\r\n<!-- URL associée -->\r\n#not_empty(#url();,<br />En ligne : <a href=\"#url();\" target=\"_blank\">#if(#extract_path(:\\/\\/([^\\/]*)\\/.,#url(););,#extract_path(:\\/\\/([^\\/]*)\\/.,#url(););[...],#extract_path(:\\/\\/([^\\/]*),#url();););</a>);\r\n\r\n<!-- affichage du résumé -->\r\n#a_empty(#resume();,<br /><br />);\r\n\r\n<!-- affichage des documents numériques -->\r\n#a_empty(#expl_num();,<br /><br />);\r\n\r\n                        </td>\r\n		</tr>\r\n	</tbody>\r\n</table>');
INSERT INTO notice_tplcode (num_notpl, notplcode_localisation, notplcode_typdoc, notplcode_niveau_biblio, notplcode_niveau_hierar, nottplcode_code) VALUES (1,0,'0','m','0','<table border=\"0\" cellpadding=\"1\" cellspacing=\"5\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"width:110px;text-align:center;\">\r\n\r\n<!-- affichage de la vignette avec un lien vers la notice / attention à personnaliser la vignette no_image.jpg en fonction du style -->\r\n<a href=\"#permalink();\">#if(#img_url();,<img src=\"#img_url();\" style=\"width:100px;\" />,<img src=\"./images/no_image.jpg\" style=\"width:100px;\" />);</a>\r\n\r\n                        </td>\r\n			<td style=\"text-align:left;\">\r\n\r\n<!-- affichage du titre + complément du titre avec un lien vers la notice -->\r\n<a href=\"#permalink();\"><font size=3>#title();#a_empty(#complement_title();, : );</font></a>\r\n\r\n<!-- affichage des 3 premiers auteurs -->\r\n#str_replace(  , ,#a_empty(#authors_by_type_with_tpl(1,3,\\, ,\\, ,0,1,70\\,71\\,72,{rejete} {name});,<br />de ););\r\n\r\n<!-- mention d\'édition / éditeur / année / page / collection -->\r\n#a_empty(#mention_edition();#ifequal(#lastchr(#mention_edition(););,., ,#not_empty(#mention_edition();,. ););#if(#publisher();,#publisher();#a_empty(#year_publication();,\\, );#a_empty(#page();,\\, );#not_empty(#collection();, (#if(#extract_path((.*)\\, ISSN,#collection(););,#extract_path((.*)\\, ISSN,#collection(););,#collection(););#a_empty(#notice_field(nocoll);, ; );));,#if(#year_publication();,#year_publication();#a_empty(#page();,\\, );,#page();););,<br />);\r\n\r\n<!-- URL associée -->\r\n#not_empty(#url();,<br />En ligne : <a href=\"#url();\" target=\"_blank\">#if(#extract_path(:\\/\\/([^\\/]*)\\/.,#url(););,#extract_path(:\\/\\/([^\\/]*)\\/.,#url(););[...],#extract_path(:\\/\\/([^\\/]*),#url();););</a>);\r\n\r\n\r\n<!-- affichage du résumé -->\r\n#a_empty(#resume();,<br /><br />);\r\n\r\n<!-- affichage des documents numériques -->\r\n#a_empty(#expl_num();,<br /><br />);\r\n\r\n                        </td>\r\n		</tr>\r\n	</tbody>\r\n</table>');
INSERT INTO notice_tplcode (num_notpl, notplcode_localisation, notplcode_typdoc, notplcode_niveau_biblio, notplcode_niveau_hierar, nottplcode_code) VALUES (1,0,'0','a','0','<table border=\"0\" cellpadding=\"1\" cellspacing=\"5\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"width:110px;text-align:center;\">\r\n\r\n<!-- affichage de la vignette avec un lien vers la notice / attention à personnaliser la vignette no_image.jpg en fonction du style -->\r\n<a href=\"#permalink();\">#if(#img_url();,<img src=\"#img_url();\" style=\"width:100px;\" />,<img src=\"./images/no_image.jpg\" style=\"width:100px;\" />);</a>\r\n\r\n                        </td>\r\n			<td style=\"text-align:left;\">\r\n\r\n<!-- affichage du titre + complément du titre avec un lien vers la notice -->\r\n<a href=\"#permalink();\"><font size=3>#title();#a_empty(#complement_title();, : );</font></a>\r\n\r\n<!-- affichage des 3 premiers auteurs -->\r\n#str_replace(  , ,#a_empty(#authors_by_type_with_tpl(1,3,\\, ,\\, ,0,1,70\\,71\\,72,{rejete} {name});,<br />de ););\r\n\r\n<br />\r\n\r\n<!-- affichage des infos du périodique : titre / numéro / date / page -->\r\nIn <i>#nom_revue();</i>#a_empty(#numero_bulletin();,\\, );#not_empty(#date_bulletin();, (#if(#extract_path((.*) [(],#date_bulletin(););,#extract_path((.*) [(],#date_bulletin(););,#year_publication(););));#a_empty(#page();,\\, );\r\n\r\n<!-- URL associée -->\r\n#not_empty(#url();,<br />En ligne : <a href=\"#url();\" target=\"_blank\">#if(#extract_path(:\\/\\/([^\\/]*)\\/.,#url(););,#extract_path(:\\/\\/([^\\/]*)\\/.,#url(););[...],#extract_path(:\\/\\/([^\\/]*),#url();););</a>);\r\n\r\n<!-- affichage du résumé -->\r\n#a_empty(#resume();,<br /><br />);\r\n\r\n<!-- affichage des documents numériques -->\r\n#a_empty(#expl_num();,<br /><br />);\r\n\r\n                        </td>\r\n		</tr>\r\n	</tbody>\r\n</table>');
INSERT INTO notice_tplcode (num_notpl, notplcode_localisation, notplcode_typdoc, notplcode_niveau_biblio, notplcode_niveau_hierar, nottplcode_code) VALUES (10,0,'0','0','0','<!-- titre tronqué + lien -->\r\n<a href=\"#permalink();\"><h3>#ellipse(#notice_field(tit1);,50,...);</h3>\r\n</a>');
INSERT INTO notice_tplcode (num_notpl, notplcode_localisation, notplcode_typdoc, notplcode_niveau_biblio, notplcode_niveau_hierar, nottplcode_code) VALUES (11,0,'0','0','0','<div class=\"listNotVt\">\r\n    <!-- vignette + lien -->\r\n    <div class=\"imgL\">\r\n        <a href=\"#permalink();\">\r\n        <img src=\"#if(#img_url();,#img_url();,./images/no_image.jpg);\"/>\r\n        </a>\r\n    </div>\r\n\r\n    <!-- titre tronqué + lien -->\r\n    <a href=\"#permalink();\">\r\n\r\n    <p class=\"titreNot\">#ellipse(#notice_field(tit1);,100,...);</p>\r\n    </a>\r\n   \r\n</div> ');
INSERT INTO notice_tplcode (num_notpl, notplcode_localisation, notplcode_typdoc, notplcode_niveau_biblio, notplcode_niveau_hierar, nottplcode_code) VALUES (12,0,'0','0','0','<div id=\"img_notice\"><a href=\"#permalink();\" title=\"#title();\">#img();</a></div>\r\n<h3><a href=\"#permalink();\" title=\"#title();\">#title();</a></h3>\r\n<p class=\"auteurNotice\">#author();</p>\r\n<p class=\"resumeNotice\">#ellipse(#resume();,300, [...]);</p>\r\n<p class=\"plusNotice\"><a style href=\"#permalink();\">Lire la suite</a></p>');
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, opac_serialcirc_demande, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, num_notice_usage, is_numeric) VALUES (68,'i','Les perles et autres contes','','','',0,'',13,0,4,0,'2012','','','978-2-07-013600-1','','','14 cm','','','','Le symbole mystérieux d\'un collier qui a une perle de trop. La réalité crue qui vient anéantir le rêve et le bonheur offerts à une jeune aristocrate insouciante. L\'aventure, dans le port d\'Anvers, d\'un écrivain malheureux, qui fuit sa propre vie... Tels sont les thèmes et les personnages de ces trois contes. Et à travers eux, Karen Blixen nous démontre que le conte est bien l\'instrument privilégié de l\'exploration des mystères de la personnalité. Le doux velours du timbre d\'Anne Brochet nous transporte dans l\'univers mystérieux des contes de Karen Blixen. Une lecture posée qui met en mouvement l\'imagination de l\'auditeur. L\'écoute en classe de ces CD est autorisée par l\'éditeur','','','Livres lus en format CD',0,'',' livres lus format cd ','m','0',6,'15,90 eur','','',' symbole mysterieux collier qui perle trop realite crue qui vient aneantir reve bonheur offerts jeune aristocrate insouciante aventure dans port anvers ecrivain malheureux qui fuit sa propre vie tels sont themes personnages ces trois contes travers eux karen blixen nous demontre que conte est bien instrument privilegie exploration mysteres personnalite doux velours timbre anne brochet nous transporte dans univers mysterieux contes karen blixen lecture posee qui met mouvement imagination auditeur ecoute classe ces cd est autorisee par editeur ',' perles autres contes ','  Les perles et autres contes   ',1,'','2012-10-24 14:42:49','2012-10-24 15:08:13','0','','2012-01-01',1,'',1,0,0,0,'',0,'0000-00-00 00:00:00',0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, opac_serialcirc_demande, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, num_notice_usage, is_numeric) VALUES (69,'a','Contes des sages d\'Afrique','','','',0,'',6,0,5,0,'2004','','','978-2-02-068730-0','179 p.','ill. en coul., couv. ill.','18 cm','','','','','','','',0,'','','m','0',7,'15 EUR','','','',' contes sages afrique ','  Contes des sages d\'Afrique   ',1,'','2012-10-24 14:42:49','2012-10-24 14:16:37','0',0x687474703A2F2F6563782E696D616765732D616D617A6F6E2E636F6D2F696D616765732F492F35314D543836444D34394C2E5F534C3530305F41413330305F2E6A7067,'2004-01-01',1,'',1,0,0,0,'',0,'0000-00-00 00:00:00',0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, opac_serialcirc_demande, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, num_notice_usage, is_numeric) VALUES (70,'a','Sagesse d\'Afrique','','','paysages et pensées',0,'',7,0,0,0,'2008','','','978-2-8100-0117-0','1 vol. (160 p.)','ill. en coul., couv. ill. en coul.','23 x 29 cm','','Contient diverses pensées, poèmes et proverbes de différents auteurs\r\nIndex','','Présentation de l\'éditeur\r\nL\'Afrique se dévoile, au fil de magnifiques photographies accompagnées de pensées, de poèmes et de proverbes emplis de philosophie, à l\'image de ce continent dont la beauté invite à la médiation. Un voyage en terre d\'émerveillement, guidé par le regard de nombreux écrivains et d\'hommes engagés, pour découvrir un espace fascinant, ses paysages, sa faune et ses habitants. ','','','Afrique;Photographies',97,'',' afrique photographies ','m','0',7,'19,90 EUR',' contient diverses pensees poemes proverbes differents auteurs index ','',' presentation editeur afrique se devoile fil magnifiques photographies accompagnees pensees poemes proverbes emplis philosophie image ce continent dont beaute invite mediation voyage terre emerveillement guide par regard nombreux ecrivains hommes engages pour decouvrir espace fascinant ses paysages sa faune ses habitants ',' sagesse afrique paysages pensees ','  Sagesse d\'Afrique   paysages et pensées',1,'','2012-10-24 14:42:49','2012-12-12 14:05:39','0','','2008-01-01',1,'',1,0,0,0,'',0,'0000-00-00 00:00:00',0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, opac_serialcirc_demande, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, num_notice_usage, is_numeric) VALUES (71,'a','Afriques','','','',0,'',8,0,0,0,'2012','','','978-2-7541-0611-5','1 vol. (non paginé [395] p.)','tout en ill., couv. ill.','28 cm','','','','Depuis plus de vingt ans Raymond Depardon a parcouru tout le continent africain auquel il a consacré plusieurs films. Il a réalisé ainsi une grande quantité de photographies dont 350 inédites sont présentées dans cet ouvrage. Ces photographies couvrent toute l\'Afrique, à travers une présentation non pas par pays mais par associations originales. Ces associations privilégient un rythme soutenu, sans temps d\'arrêt, des enchaînements qui montrent la vie au travers de sujets très variés : portraits, villes, paysages, religions, activités sociales et métiers mais aussi des conflits et la misère. A travers ses photographies, exemptes de toute volonté d\'esthétiser son propos, Raymond Depardon ne livre aucun jugement sur l\'Afrique, aucune thèse. Ce qui relie entre elles ces prises de vue, c\'est l\'impulsion de l\'?il, simplement un regard de photographe et de grand voyageur sur les paysages et les hommes qui peuplent ce continent. Pourquoi des Afriques ? Depuis 1960, année de ma première rencontre avec le continent africain à l\'âge de dix-huit ans, et jusqu\'à mon dernier voyage cet hiver au Horar, je n\'ai cessé de photographier l\'Afrique. Mais que de lieux, de temps différents ! Une vie toute entière ne suffirait pas à prétendre connaître cette Afrique. Aujourd\'hui, les prétextes, les raisons de ces voyages sont oubliés. C\'est pour cela que j\'avais envie de faire ce livre, pour rendre la liberté à toutes ces photographies et enfin réunir toutes ces Afriques, celles des pistes, des sourires, des famines et des guerres civiles. Je voulais oser ces quatre cents pages de photographies sous respiration. Je voulais étouffer devant l\'immense Afrique, me trouver comme au bord d\'une route où nous serions en panne pour plusieurs jours, envahis, à rester silencieux et à écouter. Je me souviens de chaque lieu, de chaque temps. J\'ose le désordre, il le faut. Je réunis ces photographies prises pendant quarante-cinq ans de voyages en Afrique. Raymond Depardon','','','Afrique;Photographies',97,'',' afrique photographies ','m','0',8,'25 EUR','','',' depuis plus vingt ans raymond depardon parcouru tout continent africain auquel il consacre plusieurs films il realise ainsi grande quantite photographies dont 350 inedites sont presentees dans cet ouvrage ces photographies couvrent toute afrique travers presentation non pas par pays mais par associations originales ces associations privilegient rythme soutenu sans temps arret enchainements qui montrent vie travers sujets tres varies portraits villes paysages religions activites sociales metiers mais aussi conflits misere travers ses photographies exemptes toute volonte esthetiser son propos raymond depardon ne livre aucun jugement sur afrique aucune these ce qui relie entre elles ces prises vue c est impulsion il simplement regard photographe grand voyageur sur paysages hommes qui peuplent ce continent pourquoi afriques depuis 1960 annee ma premiere rencontre avec continent africain age dix huit ans jusqu mon dernier voyage cet hiver horar je n ai cesse photographier afrique mais que lieux temps differents vie toute entiere ne suffirait pas pretendre connaitre cette afrique aujourd hui pretextes raisons ces voyages sont oublies c est pour cela que j avais envie faire ce livre pour rendre liberte toutes ces photographies enfin reunir toutes ces afriques celles pistes sourires famines guerres civiles je voulais oser ces quatre cents pages photographies sous respiration je voulais etouffer devant immense afrique me trouver comme bord route ou nous serions panne pour plusieurs jours envahis rester silencieux ecouter je me souviens chaque lieu chaque temps j ose desordre il faut je reunis ces photographies prises pendant quarante cinq ans voyages afrique raymond depardon ',' afriques ','  Afriques   ',1,'','2012-10-24 14:42:49','2012-10-24 14:11:40','0','','2012-01-01',1,'',1,0,0,0,'',0,'0000-00-00 00:00:00',0,0);
