INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, opac_serialcirc_demande, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, num_notice_usage, is_numeric) VALUES (103,'a','Fahrenheit 451','','','',0,'',13,0,21,1,'2000','3','','978-2-07-041573-1','213 p.','couv. ill. en coul.','18 cm','','','','451 degrés Fahrenheit représentent la température à laquelle un livre s\'enflamme et se consume.Dans cette société future où la lecture, source de questionnement et de réflexion, est considérée comme un acte antisocial, un corps spécial de pompiers est chargé de brûler tous les livres, dont la détention est interdite pour le bien collectif.Montag, le pompier pyromane, se met pourtant à rêver d\'un monde différent, qui ne bannirait pas la littérature et l\'imaginaire au profit d\'un bonheur immédiatement consommable. Il devient dès lors un dangereux criminel, impitoyablement poursuivi par une société qui désavoue son passé.','','','',0,'','','m','0',7,'25 F : 3,81 EUR','','',' 451 degres fahrenheit representent temperature laquelle livre s enflamme se consume dans cette societe future ou lecture source questionnement reflexion est consideree comme acte antisocial corps special pompiers est charge bruler tous livres dont detention est interdite pour bien collectif montag pompier pyromane se met pourtant rever monde different qui ne bannirait pas litterature imaginaire profit bonheur immediatement consommable il devient lors dangereux criminel impitoyablement poursuivi par societe qui desavoue son passe ',' fahrenheit 451 ','  Fahrenheit 451   ',1,'','2012-10-24 14:42:52','2012-10-24 13:32:20','0','','2000-01-01',1,'',1,0,0,0,'',0,'0000-00-00 00:00:00',0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, opac_serialcirc_demande, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, num_notice_usage, is_numeric) VALUES (104,'a','La huitième couleur','','','',3,'1',34,0,0,0,'1996','','','978-2-84172-039-2','279 p.','couv. ill. en coul.','18 cm','','','','Quatrième de couverture\r\nDans une dimension lointaine et passablement farfelue, un monde se balade à dos de quatre éléphants, eux©mêmes juchés sur la carapace de la Grande Tortue... Oui, c\'est le Disque©monde... Les habitants de la cité d\'Ankh©Morpork croyaient avoir tout vu. Et Deuxfleurs avait l\'air tellement inoffensif, bonhomme chétif, fidèlement escorté par un Bagage de bois magique déambulant sur une myriade de petites jambes. Tellement inoffensif que le Patricien avait chargé le calamiteux sorcier Rincevent de sa sécurité dans la cité quadrillée par la Guilde des Voleurs et celle des Assassins ; mission périlleuse et qui devait les conduire loin : dans une caverne de dragons ; peut©être jusqu\'au Rebord du Disque. Car Deuxfleurs était d\'une espèce plus redoutable qu\'on ne l\'imaginait : c\'était un touriste... A la lumière de l\'octarine, la huitième couleur, celle de la magie, découvrez l\'univers fantastique et cocasse de Terry Pratchett.','','','',0,' annales disque monde ','','m','0',7,'80 F','','',' quatrieme couverture dans dimension lointaine passablement farfelue monde se balade dos quatre elephants eux memes juches sur carapace grande tortue oui c est disque monde habitants cite ankh morpork croyaient avoir tout vu deuxfleurs avait air tellement inoffensif bonhomme chetif fidelement escorte par bagage bois magique deambulant sur myriade petites jambes tellement inoffensif que patricien avait charge calamiteux sorcier rincevent sa securite dans cite quadrillee par guilde voleurs celle assassins mission perilleuse qui devait conduire loin dans caverne dragons peut etre jusqu rebord disque car deuxfleurs etait espece plus redoutable qu on ne imaginait c etait touriste lumiere octarine huitieme couleur celle magie decouvrez univers fantastique cocasse terry pratchett ',' annales disque monde 1 huitieme couleur ',' annales disque monde  1 La huitième couleur   ',1,'','2012-10-24 14:42:52','2012-12-12 14:11:02','0','','1996-01-01',1,'',1,0,0,0,'',0,'0000-00-00 00:00:00',0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, opac_serialcirc_demande, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, num_notice_usage, is_numeric) VALUES (105,'a','Le huitième sortilège','','','',3,'2',34,0,0,0,'1993','','','978-2-905158-75-8','270 p.','couv. ill. en coul.','18 cm','','','','Présentation de l\'éditeur\r\nOctogénaire, borgne, chauve et édenté, Cohen le Barbare, le plus grand héros de tous les temps, réussira-t-il à tirer Deuxfleurs et Rincevent des griffes de leurs poursuivants ? Question capitale, car le tissu même du temps et de l\'espace est sur le point de passer dans l\'essoreuse. Une étoile rouge menace de percuter le Disque-Monde et la survie de celui-ci est entre les mains du sorcier calamiteux : dans son esprit (très) brumeux se tapit en effet le... huitième sortilège ! La suite de l\'épopée la plus démente de la fantasy, avec, dans les seconds rôles, une distribution prestigieuse : le Bagage, l\'In-Octavo, Herrena la harpie, Kwartz le troll, Trymon l\'enchanteur maléfique et, naturellement, La Mort...','','','',0,' annales disque monde ','','m','0',7,'77 F','','',' presentation editeur octogenaire borgne chauve edente cohen barbare plus grand heros tous temps reussira il tirer deuxfleurs rincevent griffes leurs poursuivants question capitale car tissu meme temps espace est sur point passer dans essoreuse etoile rouge menace percuter disque monde survie celui ci est entre mains sorcier calamiteux dans son esprit tres brumeux se tapit effet huitieme sortilege suite epopee plus demente fantasy avec dans seconds roles distribution prestigieuse bagage in octavo herrena harpie kwartz troll trymon enchanteur malefique naturellement mort ',' annales disque monde 2 huitieme sortilege ',' annales disque monde  2 Le huitième sortilège   ',1,'','2012-10-24 14:42:52','2012-12-12 14:11:51','0','','1993-01-01',1,'',1,0,0,0,'',0,'0000-00-00 00:00:00',0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, opac_serialcirc_demande, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, num_notice_usage, is_numeric) VALUES (106,'a','La triste fin du petit enfant huître et autres histoires','','','',0,'',35,0,24,0,'2008','','','978-2-264-04873-8','128 p.','','17 cm','','','','Fidèle à son univers d\'une inventivité si  particulière, mêlant crauté et tendresse,  macabre et poésie, Tim Burton donne le jour à une  étonnante famille d\'enfants solitaires, étranges et  différents, qui ne tarderont pas à nous horrifier,  à nous émouvoir et à nous faire rire.  Un livre pour l\'enfant qui est en nous','','','Littérature;Romans contemporains;Littérature au format poche;Romans en Poche',82,'',' litterature romans contemporains litterature format poche romans poche ','m','0',6,'10,14 eur','','',' fidele son univers inventivite si particuliere melant craute tendresse macabre poesie tim burton donne jour etonnante famille enfants solitaires etranges differents qui ne tarderont pas nous horrifier nous emouvoir nous faire rire livre pour enfant qui est nous ',' triste fin petit enfant huitre autres histoires ','  La triste fin du petit enfant huître et autres histoires   ',1,'','2012-10-24 14:42:52','2012-10-24 13:27:36','0','','2008-01-01',1,'',1,0,0,0,'',0,'0000-00-00 00:00:00',0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, opac_serialcirc_demande, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, num_notice_usage, is_numeric) VALUES (107,'a','Tim Burton','','','',0,'',36,0,25,0,'','171','','978-2-35880-032-7','','','','','','','Présentation de l\'éditeur\r\nIl était une fois un garçon qui aimait inventer des histoires. Il se dit qu\'un homme déguisé en chauve-souris, ça ferait peur aux méchants. Il pense à la petite fille qui passe de l\'autre côté du miroir et découvre un monde merveilleux. A la femme qui se prend pour un chat et qui joue avec l\'homme pingouin. Il se dit qu\'une citrouille ne remplacera jamais le Père Noël, mais qu\'elle pourrait avoir envie d\'essayer. Il imagine ce qui se passerait si les habitants de Mars attaquaient la Terre... Son rêve, c\'était de rassembler toutes ces histoires et tous leurs personnages. Aujourd\'hui, le petit garçon est devenu grands et il fait du cinéma. Le tour du monde des musées en BD et en jeu .: le musée du Palais a Pékin.','','','Jeunesse;L\'Univers des Enfants',71,'',' jeunesse univers enfants ','m','0',6,'7,90 EUR','','',' presentation editeur il etait fois garcon qui aimait inventer histoires il se dit qu homme deguise chauve souris ca ferait peur mechants il pense petite fille qui passe autre cote miroir decouvre monde merveilleux femme qui se prend pour chat qui joue avec homme pingouin il se dit qu citrouille ne remplacera jamais pere noel mais qu elle pourrait avoir envie essayer il imagine ce qui se passerait si habitants mars attaquaient terre son reve c etait rassembler toutes ces histoires tous leurs personnages aujourd hui petit garcon est devenu grands il fait cinema tour monde musees bd jeu musee palais pekin ',' tim burton ','  Tim Burton   ',1,'','2012-10-24 14:42:52','2012-12-12 14:08:39','0','','0000-00-00',1,'',1,0,0,0,'',0,'0000-00-00 00:00:00',0,0);
