INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, opac_serialcirc_demande, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, num_notice_usage, is_numeric) VALUES (110,'g','Edward aux mains d\'argent','','','',0,'',39,0,0,0,'2011','','','','1 DVD (1 h 45 min)','16/9, coul. (PAL), son., surround (Dolby)','','','','','Synopsis\r\nEdward est la création d\'un savant génial. Il ne possède pas de vrais mains, mais des lames très tranchantes à la place des doigts. Il peut réaliser avec ses instruments de véritables oeuvres d\'art, qui vont provoquer la curiosité et l\'enthousiasme de toute la ville. Mais il est capable de blesser et de faire mal quand il ne se contrôle plus... ','','','',0,'','','m','0',1,'','','',' synopsis edward est creation savant genial il ne possede pas vrais mains mais lames tres tranchantes place doigts il peut realiser avec ses instruments veritables oeuvres art qui vont provoquer curiosite enthousiasme toute ville mais il est capable blesser faire mal quand il ne se controle plus ',' edward mains argent ','  Edward aux mains d\'argent   ',1,'','2012-10-24 14:49:09','2012-12-12 13:43:08','0',0x687474703A2F2F6563782E696D616765732D616D617A6F6E2E636F6D2F696D616765732F492F35315A45626B4F53774F4C2E5F41413131355F2E6A7067,'2011-01-01',1,'',1,0,0,0,'',0,'0000-00-00 00:00:00',0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, opac_serialcirc_demande, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, num_notice_usage, is_numeric) VALUES (111,'g','Beetlejuice','','','',0,'',40,0,28,2,'2010','079','','','1 DVD vidéo zone 2 (1 h 32 min)','16/9, coul. (PAL), son., surround','','','','','Synopsis\r\nBarbara et Adam forment un adorable couple. Hélas survient un stupide accident de voiture et les voilà devenus fantômes obligés de hanter les murs de leur propre demeure ! Quelle n\'est pas leur déception lorsqu\'ils la voient livrée aux mains d\'une famille excentrique dont les membres évoluent entre hystérie et stupidité. Barbara et Adam tentent de les chasser. En vain. La seule solution : faire appel à Beetlejuice, un fantôme exorciseur de vivants... ','','','',0,'','','m','0',1,'','','',' synopsis barbara adam forment adorable couple helas survient stupide accident voiture voila devenus fantomes obliges hanter murs leur propre demeure quelle n est pas leur deception lorsqu ils voient livree mains famille excentrique dont membres evoluent entre hysterie stupidite barbara adam tentent chasser vain seule solution faire appel beetlejuice fantome exorciseur vivants ',' beetlejuice ','  Beetlejuice   ',1,'','2012-10-24 14:51:53','2012-12-12 12:24:30','0',0x687474703A2F2F6563782E696D616765732D616D617A6F6E2E636F6D2F696D616765732F492F353132425A43315A39304C2E5F534C3530305F41413330305F2E6A7067,'2010-01-01',1,'',1,0,0,0,'',0,'0000-00-00 00:00:00',0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, opac_serialcirc_demande, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, num_notice_usage, is_numeric) VALUES (112,'g','Big Fish','','','',0,'',41,0,0,0,'2004','','','','1 DVD zone 2 (2 h 51 min)','coul. (PAL), sonore','','','','','Synopsis\r\nApprenant qu\'Edward, son père, est sur le point de mourir, Will décide de se rapprocher de lui pour enfin connaître cet homme qui a bercé son enfance avec des contes plus ou moins fantastiques dans lesquels il se mettait en scène aux côtés de personnages extravagants et extraordinaires...','','','',0,'','','m','0',1,'','','',' synopsis apprenant qu edward son pere est sur point mourir will decide se rapprocher lui pour enfin connaitre cet homme qui berce son enfance avec contes plus ou moins fantastiques dans lesquels il se mettait scene cotes personnages extravagants extraordinaires ',' big fish ','  Big Fish   ',1,'','2012-10-24 14:55:20','2012-12-12 12:25:06','0',0x687474703A2F2F6563782E696D616765732D616D617A6F6E2E636F6D2F696D616765732F492F353130573251435357584C2E5F41413136305F2E6A7067,'2004-01-01',1,'',1,0,0,0,'',0,'0000-00-00 00:00:00',0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, opac_serialcirc_demande, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, num_notice_usage, is_numeric) VALUES (113,'g','Les noces funèbres','','','',0,'',40,0,0,0,'2008','','','','1 DVD zone 2 (1 h 17 min)','19/9, coul. (PAL), son., surround (Dolby)','','','','','Synopsis\r\nAu XIXe siècle, dans un village d\'Europe de l\'est, Victor, un jeune homme, découvre le monde des morts après avoir épousé, sans le vouloir, le cadavre d\'une mystérieuse mariée. Pendant son voyage, sa promise, Victoria l\'attend désespérément dans le monde des vivants. Bien que la vie au Royaume des Morts s\'avère beaucoup plus animée et joyeuse que sa véritable existence, Victor apprend que rien au monde, pas même la mort, ne pourra briser son amour pour sa femme... ','','','',0,'','','m','0',1,'','','',' synopsis xixe siecle dans village europe est victor jeune homme decouvre monde morts apres avoir epouse sans vouloir cadavre mysterieuse mariee pendant son voyage sa promise victoria attend desesperement dans monde vivants bien que vie royaume morts s avere beaucoup plus animee joyeuse que sa veritable existence victor apprend que rien monde pas meme mort ne pourra briser son amour pour sa femme ',' noces funebres ','  Les noces funèbres   ',1,'','2012-10-24 14:57:40','2012-12-12 14:03:11','0',0x687474703A2F2F6563782E696D616765732D616D617A6F6E2E636F6D2F696D616765732F492F353172676F305930666F4C2E5F41413136305F2E6A7067,'2008-01-01',1,'',1,0,0,0,'',0,'0000-00-00 00:00:00',0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, opac_serialcirc_demande, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, num_notice_usage, is_numeric) VALUES (114,'g','Charlie et la chocolaterie','','','',0,'',40,0,0,0,'2006','','','','2 DVD zone 2 (1 h 50 min)','16/9, coul. (PAL), son., surround (Dolby)','','','','','Synopsis\r\nQuelles sont les merveilles qui t\'attendent dans l\'usine de Willy Wonka ? Pars à la découverte de vastes étendues d\'herbe sucrée au bon goût de menthe dans la Salle du Chocolat... Navigue sur la Rivière de Chocolat dans un grand bateau en sucre rose... Essaye le Gobestoppeur sans fin dans la Salle des Inventions... Observe les talentueux écureuils de la Salle de Tri des Noix et voyage en ascenseur de verre jusqu\'à la Salle de Télévision. Tu y trouveras une montagne d\'humour saupoudrée d\'un peu de mystère... et une aventure aussi savoureuse et agréable qu\'une tablette de Délice Fondant Wonka Guimauve-Caramel... ','','','',0,'','','m','0',1,'','','',' synopsis quelles sont merveilles qui attendent dans usine willy wonka pars decouverte vastes etendues herbe sucree bon gout menthe dans salle chocolat navigue sur riviere chocolat dans grand bateau sucre rose essaye gobestoppeur sans fin dans salle inventions observe talentueux ecureuils salle tri noix voyage ascenseur verre jusqu salle television tu y trouveras montagne humour saupoudree peu mystere aventure aussi savoureuse agreable qu tablette delice fondant wonka guimauve caramel ',' charlie chocolaterie ','  Charlie et la chocolaterie   ',1,'','2012-10-24 15:00:13','2012-12-12 12:25:56','0',0x687474703A2F2F6563782E696D616765732D616D617A6F6E2E636F6D2F696D616765732F492F353145414E5A443052354C2E5F41413136305F2E6A7067,'2006-01-01',1,'',1,0,0,0,'',0,'0000-00-00 00:00:00',0,0);
