INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, opac_serialcirc_demande, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, num_notice_usage, is_numeric) VALUES (122,'a','N° 393 - novembre 2011 - L\'Île de Pâques',NULL,'','Le rêve ultime des voyageurs',0,'',0,0,0,0,'2011',NULL,'','','','','','','','ÉVASION - La dernière frontière du Pacifique\r\nÀ des milliers de kilomètres de toute terre émergée, l’île de Pâques et ses statues géantes fascinent toujours les voyageurs.\r\n\r\nMODES DE VIE - Le Grand Paris\r\nÀ quoi ressemblera le Grand Paris ? Un métro de 200 kilomètres, un port gigantesque à Achères, une Silicon Valley à Saclay… La future mégapole commence à dévoiler son nouveau visage.\r\n\r\nENVIRONNEMENT - L\'iPhone est-il écolo ?\r\nÉtape par étape, l’analyse de l’impact environnemental du petit bijou d’Apple.\r\n\r\nVOYAGE - La nouvelle vie de Cracovie\r\nLa cité polonaise est l’un des lieux les plus touristiques de l’ancien bloc de l’Est. Grâce à sa richesse culturelle et à sa jeunesse qui crée une ambiance de «movida».\r\n\r\nPARTIR - Quoi de neuf à Bruxelles ?\r\nMalgré la crise institutionnelle qui paralyse le pays, la capitale belge n’a pas perdu sa créativité. Tables, hôtels, shopping… Tour d’horizon des nouvelles adresses.\r\n\r\nGÉOPOLITIQUE - Comment la Chine redessine le monde\r\nEn Grèce, en Birmanie, en Zambie… Partout, les Chinois financent et bâtissent des ports, des routes, des hôpitaux. C’est la phase nouvelle du «zouchuqu», leur stratégie de conquête tous azimuts.\r\n\r\nLE MONDE EN CARTES - Pourquoi la Kapisa est dans l’oeil du cyclone ?\r\nProche de Kaboul, cette province est la zone de tous les dangers pour les militaires français.\r\n\r\nGRANDE SÉRIE : LE LITTORAL FRANÇAIS - LA NORMANDIE\r\nNotre photographe livre son coup d’oeil sur les hauts lieux de la côte normande. Et notre journaliste analyse les enjeux du moment sur le plan du tourisme et de l’environnement. ','','','','',0,'','','b','2',1,'','',' evasion derniere frontiere pacifique milliers kilometres toute terre emergee ile paques ses statues geantes fascinent toujours voyageurs modes vie grand paris quoi ressemblera grand paris metro 200 kilometres port gigantesque acheres silicon valley saclay future megapole commence devoiler son nouveau visage environnement iphone est il ecolo etape par etape analyse impact environnemental petit bijou apple voyage nouvelle vie cracovie cite polonaise est lieux plus touristiques ancien bloc est grace sa richesse culturelle sa jeunesse qui cree ambiance movida partir quoi neuf bruxelles malgre crise institutionnelle qui paralyse pays capitale belge n pas perdu sa creativite tables hotels shopping tour horizon nouvelles adresses geopolitique comment chine redessine monde grece birmanie zambie partout chinois financent batissent ports routes hopitaux c est phase nouvelle zouchuqu leur strategie conquete tous azimuts monde cartes pourquoi kapisa est dans oeil cyclone proche kaboul cette province est zone tous dangers pour militaires francais grande serie littoral francais normandie notre photographe livre son coup oeil sur hauts lieux cote normande notre journaliste analyse enjeux moment sur plan tourisme environnement ','',' n 393 novembre 2011 ile paques reve ultime voyageurs ','  N° 393 - novembre 2011 - L\'Île de Pâques   Le rêve ultime des voyageurs',1,'','2012-10-24 17:26:11','2012-11-20 08:29:44','0',,'2011-11-01',1,'',1,0,0,0,'',0,'0000-00-00 00:00:00',0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, opac_serialcirc_demande, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, num_notice_usage, is_numeric) VALUES (123,'a','N° 402 - août 2012 - Compostelle, Shikoku, Lalibela... Les chemins de la sagesse',NULL,'','',0,'',0,0,0,0,'2012',NULL,'','','','','','','','LE MONDE QUI CHANGE\r\nLe patrimoine de la Syrie sous la menace.\r\n\r\nLES HÉROS D\'AUJOURD\'HUI\r\nCe chirurgien indien qui prend à cœur la santé de son pays.\r\n\r\nLE GOÛT DE GEO\r\nLe «dim-sum», un microfestin à la chinoise.\r\n\r\nÉVASION - Dans le sillage d\'Ulysse\r\nHeureux qui comme le héros d\'Homère a fait un beau voyage... GEO a suivi ses pas en Méditerranée.\r\n\r\nESCALE - Jean Didier Urbain\r\nVite parcouru, mal lu.\r\n\r\nMODES DE VIE - A la vie, à la mer\r\nReportage sur ces marins pêcheurs qui écument les océans glacés et bravent les tempêtes.\r\n\r\nENVIRONNEMENT - Faut-il se préparer aux grandes sécheresses ?\r\nIl fait plus sec et plus chaud. Résultat, la terre a soif et les agriculteurs trinquent.\r\n\r\nVOYAGE - Le renouveau des chemins sacrés\r\nLes marcheurs affluent vers les routes spirituelles à la recherche du grand voyage intérieur.\r\n\r\nLE BON PLAN - Le Bilbao des Bilbotars\r\n\r\nGÉOPOLITIQUE - Terres fertiles à louer\r\nDe puissants investisseurs étrangers trustent les meilleurs champs des pays du Sud. Néocolonialisme ou développement agricole ?\r\n\r\nLE MONDE EN CARTES - Des îles très disputées\r\n\r\nGRANDE SÉRIE - La France des villages\r\nPérigord et Quercy : panorama mensuel des pépites du terroir.','','','','',0,'','','b','2',1,'','',' monde qui change patrimoine syrie sous menace heros aujourd hui ce chirurgien indien qui prend coeur sante son pays gout geo dim sum microfestin chinoise evasion dans sillage ulysse heureux qui comme heros homere fait beau voyage geo suivi ses pas mediterranee escale jean didier urbain vite parcouru mal lu modes vie vie mer reportage sur ces marins pecheurs qui ecument oceans glaces bravent tempetes environnement faut il se preparer grandes secheresses il fait plus sec plus chaud resultat terre soif agriculteurs trinquent voyage renouveau chemins sacres marcheurs affluent vers routes spirituelles recherche grand voyage interieur bon plan bilbao bilbotars geopolitique terres fertiles louer puissants investisseurs etrangers trustent meilleurs champs pays sud neocolonialisme ou developpement agricole monde cartes iles tres disputees grande serie france villages perigord quercy panorama mensuel pepites terroir ','',' n 402 aout 2012 compostelle shikoku lalibela chemins sagesse ','  N° 402 - août 2012 - Compostelle, Shikoku, Lalibela... Les chemins de la sagesse   ',1,'','2012-10-24 17:30:07','2012-11-20 08:29:44','0',0x687474703A2F2F7777772E67656F2E66722F7661722F67656F2F73746F726167652F696D616765732F6D656469612F636F75766572747572652D67656F2D6E2D3430322F313133353938332D312D6672652D46522F636F75766572747572652D67656F2D6E2D3430325F363230783436352E6A7067,'2012-08-01',1,'',1,0,0,0,'',0,'0000-00-00 00:00:00',0,0);
