INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, opac_serialcirc_demande, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, num_notice_usage, is_numeric) VALUES (125,'l','Bibliothécaire de soi-même',NULL,'','',0,'',0,0,0,0,'2010',NULL,'','','',NULL,NULL,NULL,'','','Les bibliothèques publiques ont souvent pour origine des collections privées. Mais la fréquentation de ces bibliothèques n\'empêche pas, accompagne même, le goût pour constituer sa bibliothèque privée, « la reconstitution à son usage propre d\'une sorte de bibliothèque publique ». La gestion de ces bibliothèques privées se heurte aux mêmes problèmes que les bibliothèques institutionnelles, comme le classement, le rangement, mais aussi la politique d\'acquisition, même si le caractère privé de sa bibliothèque autorise de nombreuses licences au propriétaire des livres, « bibliothécaire de soi-même ». L\'obligation de conservation et d\'entretien est évidente, si celle de désherbage, désormais largement pratiqué dans les bibliothèques publiques, l\'est moins - tout comme le catalogage, et a fortiori le prêt.','','','',0,'','','a','2',1,'','','',' bibliotheques publiques ont souvent pour origine collections privees mais frequentation ces bibliotheques n empeche pas accompagne meme gout pour constituer sa bibliotheque privee reconstitution son usage propre sorte bibliotheque publique gestion ces bibliotheques privees se heurte memes problemes que bibliotheques institutionnelles comme classement rangement mais aussi politique acquisition meme si caractere prive sa bibliotheque autorise nombreuses licences proprietaire livres bibliothecaire soi meme obligation conservation entretien est evidente si celle desherbage desormais largement pratique dans bibliotheques publiques est moins tout comme catalogage fortiori pret ',' bibliothecaire soi meme ','  Bibliothécaire de soi-même   ',1,'','2012-10-24 17:41:02','2013-01-15 13:55:19','0',0x687474703A2F2F6262662E656E737369622E66722F73697465732F6262662E656E737369622E66722F7468656D65732F4242462F696D616765732F636F6D6D756E2F4242665F6C6F676F5F696D7072657373696F6E2E706E67,'2010-11-01',1,'',1,0,0,0,'',0,'0000-00-00 00:00:00',0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, opac_serialcirc_demande, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, num_notice_usage, is_numeric) VALUES (126,'l','Voyages en BM',NULL,'','',0,'',0,0,0,0,'2010',NULL,'','','',NULL,NULL,NULL,'','','La trajectoire d\'un usager des bibliothèques publiques, de l\'enfance à aujourd\'hui : autodidacte, il fréquente assidûment la bibliothèque municipale de Montreuil-sous-Bois, « copropriétaire d\'une BM unique dans la commune... Ma première patrie fut cette bibliothèque » ; le contact permanent des livres, le passage difficile de l\'adolescence, puis le « boulot d\'auteur », toujours accompagné des bibliothèques. « Aujourd\'hui, je ne ressemble pas à mes gosses. À cause ou grâce à ces livres empruntés chaque semaine, j\'ai quitté une classe sociale... sans jamais en trouver une autre de rechange. »','','','',0,'','','a','2',1,'','','',' trajectoire usager bibliotheques publiques enfance aujourd hui autodidacte il frequente assidument bibliotheque municipale montreuil sous bois coproprietaire bm unique dans commune ma premiere patrie fut cette bibliotheque contact permanent livres passage difficile adolescence puis boulot auteur toujours accompagne bibliotheques aujourd hui je ne ressemble pas mes gosses cause ou grace ces livres empruntes chaque semaine j ai quitte classe sociale sans jamais trouver autre rechange ',' voyages bm ','  Voyages en BM   ',1,'','2012-10-24 17:44:30','2012-11-20 08:29:44','0',0x687474703A2F2F6262662E656E737369622E66722F73697465732F6262662E656E737369622E66722F7468656D65732F4242462F696D616765732F636F6D6D756E2F4242665F6C6F676F5F696D7072657373696F6E2E706E67,'2010-11-01',1,'',1,0,0,0,'',0,'0000-00-00 00:00:00',0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, opac_serialcirc_demande, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, num_notice_usage, is_numeric) VALUES (127,'l','L\'abeille et le bibliothécaire ou éthique du libre et lecture publique en zone rurale',NULL,'','',0,'',0,0,0,0,'2012',NULL,'','','',NULL,NULL,NULL,'','','Mariant évolution des techniques et analyse des territoires ruraux, cet article se veut une réflexion (et une incitation) sur le travail en commun, une « théorie de la pratique », la mise en oeuvre professionnelle et partagée de la société de la connaissance. L\'exemple du RISOM (Réseau intercommunal et solidaire des médiathèques de Tence, St-Jeures et Le Mazet-St-Voy, Haute-Loire), qui propose le partage d\'informations sur des projets d\'animation, leurs outils et leurs usages, vient à l\'appui et en illustration de cette analyse.','','','',0,'','','a','2',1,'','','',' mariant evolution techniques analyse territoires ruraux cet article se veut reflexion incitation sur travail commun theorie pratique mise oeuvre professionnelle partagee societe connaissance exemple risom reseau intercommunal solidaire mediatheques tence st jeures mazet st voy haute loire qui propose partage informations sur projets animation leurs outils leurs usages vient appui illustration cette analyse ',' abeille bibliothecaire ou ethique libre lecture publique zone rurale ','  L\'abeille et le bibliothécaire ou éthique du libre et lecture publique en zone rurale   ',1,'http://bbf.enssib.fr/sites/bbf.enssib.fr/themes/BBF/images/commun/BBf_logo_impression.png','2012-10-24 17:48:22','2014-11-18 15:07:06','0','','2012-09-01',1,'',1,0,0,0,'',0,'0000-00-00 00:00:00',0,0);
