INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, opac_serialcirc_demande, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, num_notice_usage, is_numeric) VALUES (129,'a','Georges',NULL,'','petit-petit-petit magazine',0,'',49,0,0,0,'2010-',NULL,'','2110-8749',NULL,NULL,NULL,NULL,'','','Le concept de Georges\r\n\r\nBienvenue dans l’univers de Georges, petit – petit – petit magazine, revue alternative trimestrielle créée par les Éditions Grains de Sel, pour les enfants ni trop petits ni trop grands (dès 7-8 ans et jusqu’à 12 ans). Mais aussi pour les plus grands qui s’intéressent au graphisme et à l’illustration.\r\n \r\nMais qui est Georges ?\r\nUn magazine décalé et exigeant qui stimule la curiosité et revisite les traitements traditionnels des magazines pour enfants.\r\n\r\nQuels sont ses atouts ?\r\nUn graphisme épuré  et un thème original pour chaque numéro, sur un beau papier offset et recyclé, avec des illustrateurs aux univers sensibles et un second degré qui séduit les enfants (et même leurs parents).\r\n\r\nComment se présente-t-il ?\r\nPartie 1 – des HISTOIRES vraies, courtes, longues ou à l’envers.\r\nPartie 2 – des JEUX à colorier, calculer ou déchiffrer autour du thème du numéro.\r\nPartie 3 – des RUBRIQUES-À-BRAC pour découvrir des métiers, langues étrangères, scènes de films ou expériences scientifiques, mais de façon toujours farfelue&#8201;!','http://www.magazinegeorges.com/','','',0,'','','s','1',1,'','','',' concept georges bienvenue dans univers georges petit petit petit magazine revue alternative trimestrielle creee par editions grains sel pour enfants ni trop petits ni trop grands 7 8 ans jusqu 12 ans mais aussi pour plus grands qui s interessent graphisme illustration mais qui est georges magazine decale exigeant qui stimule curiosite revisite traitements traditionnels magazines pour enfants quels sont ses atouts graphisme epure theme original pour chaque numero sur beau papier offset recycle avec illustrateurs univers sensibles second degre qui seduit enfants meme leurs parents comment se presente il partie 1 histoires vraies courtes longues ou envers partie 2 jeux colorier calculer ou dechiffrer autour theme numero partie 3 rubriques brac pour decouvrir metiers langues etrangeres scenes films ou experiences scientifiques mais facon toujours farfelue 8201 ',' georges petit petit petit magazine ','  Georges   petit-petit-petit magazine',1,'','2012-10-24 18:05:03','2012-11-20 08:29:44','0',0x687474703A2F2F7777772E6D6167617A696E6567656F726765732E636F6D2F66722F77702D636F6E74656E742F7468656D65732F626363742F696D616765732F6C6F676F5F666F6F7465722E676966,'2010-01-01',1,'',1,0,0,0,'',0,'0000-00-00 00:00:00',0,0);
INSERT INTO notices (notice_id, typdoc, tit1, tit2, tit3, tit4, tparent_id, tnvol, ed1_id, ed2_id, coll_id, subcoll_id, year, nocoll, mention_edition, code, npages, ill, size, accomp, n_gen, n_contenu, n_resume, lien, eformat, index_l, indexint, index_serie, index_matieres, niveau_biblio, niveau_hierar, origine_catalogage, prix, index_n_gen, index_n_contenu, index_n_resume, index_sew, index_wew, statut, commentaire_gestion, create_date, update_date, signature, thumbnail_url, date_parution, opac_visible_bulletinage, indexation_lang, opac_serialcirc_demande, map_echelle_num, map_projection_num, map_ref_num, map_equinoxe, notice_is_new, notice_date_is_new, num_notice_usage, is_numeric) VALUES (130,'a','Numéro Moustache',NULL,'','',0,'',0,0,0,0,'2012',NULL,'','','','','','','','','Pour ce numéro, Georges vous propose :\r\nPartie 1 : des histoires\r\nPartie 2 : des jeux\r\nPartie 3 : des rubriques-à-brac\r\n+ un lexique\r\nGeoges vous souhaite, Mesdames et Messieurs, une agréable lecture !','http://www.magazinegeorges.com/les-numeros/moustache/','','',0,'','','b','2',1,'','','',' pour ce numero georges vous propose partie 1 histoires partie 2 jeux partie 3 rubriques brac lexique geoges vous souhaite mesdames messieurs agreable lecture ',' numero moustache ','  Numéro Moustache   ',1,'','2012-10-24 18:09:18','2012-12-12 12:20:12','0',0x687474703A2F2F7777772E6D6167617A696E6567656F726765732E636F6D2F66722F77702D636F6E74656E742F75706C6F6164732F323031312F30342F6D6F757374616368652E6A7067,'2012-10-24',1,'',1,0,0,0,'',0,'0000-00-00 00:00:00',0,0);
